export const envelope = [48, 36, 48];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  function put(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      api.set(ix, iy, iz, block);
    }
  }

  const terrainTop = new Map();

  function footing(x, z) {
    const ix = Math.floor(x);
    const iz = Math.floor(z);
    if (ix < 0 || ix >= W || iz < 0 || iz >= D) {
      return;
    }

    const key = ix + ":" + iz;
    let top = terrainTop.get(key);

    if (top === undefined) {
      let h = api.heightAt(ix, iz);
      if (!Number.isFinite(h)) {
        h = 0;
      }
      top = Math.max(0, Math.min(4, Math.ceil(h)));
      terrainTop.set(key, top);
    }

    for (let y = 0; y <= top; y++) {
      put(
        ix,
        y,
        iz,
        y === 0 ? "minecraft:deepslate" : "minecraft:cobbled_deepslate"
      );
    }
  }

  for (let x = 3; x <= 44; x++) {
    for (let z = 5; z <= 43; z++) {
      const dx = (x - 24) / 16;
      const dz = (z - 28) / 15;
      const centralShelf = dx * dx + dz * dz <= 1;
      const quay = z >= 6 && z <= 14;
      const streetApron = z === 5 && x >= 7 && x <= 41;

      if (centralShelf || quay || streetApron) {
        footing(x, z);

        if (quay && (x * 13 + z * 7) % 9 < 4) {
          put(
            x,
            0,
            z,
            (x + z) % 5 === 0
              ? "minecraft:cracked_stone_bricks"
              : "minecraft:stone_bricks"
          );
        }

        if (centralShelf && (x * 5 + z * 11) % 17 === 0) {
          put(x, 0, z, "minecraft:prismarine");
        }
      }
    }
  }

  function ruinChunk(x0, x1, z0, z1, maxHeight, primary, alternate) {
    for (let x = x0; x <= x1; x++) {
      for (let z = z0; z <= z1; z++) {
        const mark = (x * 31 + z * 17 + x0 * 7 + z0 * 11) % 19;
        if (mark === 0 || (mark === 1 && (x + z) % 2 === 0)) {
          continue;
        }

        const height =
          1 + ((x * 7 + z * 11 + x0 * 3 + z0) % maxHeight);

        for (let y = 1; y <= height; y++) {
          let block = primary;
          if ((x * 3 + z * 5 + y * 7) % 13 === 0) {
            block = alternate;
          }
          put(x, y, z, block);
        }
      }
    }
  }

  ruinChunk(
    4,
    12,
    8,
    12,
    3,
    "minecraft:stone_bricks",
    "minecraft:cracked_stone_bricks"
  );
  ruinChunk(
    15,
    21,
    7,
    11,
    4,
    "minecraft:quartz_block",
    "minecraft:calcite"
  );
  ruinChunk(
    25,
    32,
    8,
    13,
    3,
    "minecraft:polished_deepslate",
    "minecraft:stone_bricks"
  );
  ruinChunk(
    36,
    44,
    7,
    12,
    4,
    "minecraft:stone_bricks",
    "minecraft:cracked_stone_bricks"
  );

  function brokenColumn(x, z, height, mainBlock) {
    footing(x, z);
    for (let dx = 0; dx < 2; dx++) {
      for (let dz = 0; dz < 2; dz++) {
        for (let y = 1; y <= height; y++) {
          let block = mainBlock;
          if ((x + z + dx + dz + y) % 6 === 0) {
            block = "minecraft:calcite";
          }
          put(x + dx, y, z + dz, block);
        }
      }
    }
  }

  brokenColumn(7, 9, 6, "minecraft:quartz_block");
  brokenColumn(18, 8, 4, "minecraft:calcite");
  brokenColumn(29, 10, 5, "minecraft:iron_block");
  brokenColumn(40, 8, 7, "minecraft:quartz_block");
  brokenColumn(12, 12, 3, "minecraft:stone_bricks");

  function paintSkin(cx, cy, cz, rx, ry, rz, variant) {
    const x0 = Math.floor(cx - rx);
    const x1 = Math.ceil(cx + rx);
    const y0 = Math.floor(cy - ry);
    const y1 = Math.ceil(cy + ry);
    const z0 = Math.floor(cz - rz);
    const z1 = Math.ceil(cz + rz);

    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          const nx = (x - cx) / rx;
          const ny = (y - cy) / ry;
          const nz = (z - cz) / rz;
          const q = nx * nx + ny * ny + nz * nz;

          if (q <= 1.000001) {
            const code =
              (x * 7 + y * 11 + z * 13 + variant * 17) % 17;
            let block = "minecraft:dark_prismarine";

            if (q > 0.7 && code % 7 < 2) {
              block = "minecraft:prismarine_bricks";
            } else if (code % 13 === 0) {
              block = "minecraft:prismarine";
            } else if (variant === 3 && code % 11 === 0) {
              block = "minecraft:prismarine";
            }

            put(x, y, z, block);
          }
        }
      }
    }
  }

  paintSkin(24, 7, 28, 8, 6, 7, 3);
  paintSkin(24, 17, 28, 11, 11, 9, 1);
  paintSkin(24, 24, 27, 8, 9, 7, 2);
  paintSkin(24, 19, 21, 7, 7, 4, 4);

  function dorsalFin(
    cx,
    baseY,
    topY,
    baseZ,
    maxWidth,
    maxDepth,
    block
  ) {
    const span = topY - baseY;

    for (let y = baseY; y <= topY; y++) {
      const t = span === 0 ? 1 : (y - baseY) / span;
      const width = Math.max(1, Math.round(maxWidth * (1 - t)));
      const depth = Math.max(1, Math.round(maxDepth * (1 - t)));

      for (let x = Math.floor(cx - width); x <= Math.ceil(cx + width); x++) {
        for (let z = baseZ; z <= baseZ + depth; z++) {
          put(x, y, z, block);
        }
      }
    }
  }

  dorsalFin(
    24,
    17,
    35,
    33,
    4,
    2,
    "minecraft:oxidized_copper"
  );
  dorsalFin(
    17,
    13,
    30,
    32,
    2,
    2,
    "minecraft:prismarine_bricks"
  );
  dorsalFin(
    31,
    13,
    30,
    32,
    2,
    2,
    "minecraft:prismarine_bricks"
  );

  for (let y = 20; y <= 34; y += 2) {
    put(24, y, 33, "minecraft:prismarine_bricks");
  }

  function sideFin(sign) {
    const inner = sign < 0 ? 16 : 32;
    const steps = 11;

    for (let i = 0; i <= steps; i++) {
      const x = inner + sign * i;
      const t = i / steps;
      const centerY = Math.round(16 - 3 * t);
      const halfY = Math.max(1, Math.round(4 - 3 * t));
      const halfZ = Math.max(1, Math.round(3 - 2 * t));

      for (let y = centerY - halfY; y <= centerY + halfY; y++) {
        for (let z = 28 - halfZ; z <= 28 + halfZ; z++) {
          const block =
            i % 3 === 0
              ? "minecraft:oxidized_copper"
              : "minecraft:dark_prismarine";
          put(x, y, z, block);
        }
      }
    }
  }

  sideFin(-1);
  sideFin(1);

  const plates = [
    [20, 29, 32],
    [24, 32, 27],
    [28, 29, 32],
    [17, 22, 24],
    [31, 22, 24],
    [13, 18, 28],
    [35, 18, 28],
    [19, 11, 29],
    [29, 11, 29]
  ];

  for (let i = 0; i < plates.length; i++) {
    const p = plates[i];
    put(p[0], p[1], p[2], "minecraft:prismarine_bricks");
  }

  put(24, 33, 27, "minecraft:sea_lantern");
  put(20, 29, 32, "minecraft:sea_lantern");
  put(28, 29, 32, "minecraft:sea_lantern");
  put(17, 22, 24, "minecraft:sea_lantern");

  for (let y = 15; y <= 21; y += 2) {
    put(17, y, 22, "minecraft:cyan_concrete");
    put(31, y, 22, "minecraft:cyan_concrete");
  }

  function fillTube(cx, cy, cz, radius, block) {
    const ry = Math.max(1.55, radius * 0.78);
    const x0 = Math.floor(cx - radius);
    const x1 = Math.ceil(cx + radius);
    const y0 = Math.floor(cy - ry);
    const y1 = Math.ceil(cy + ry);
    const z0 = Math.floor(cz - radius);
    const z1 = Math.ceil(cz + radius);

    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          const nx = (x - cx) / radius;
          const ny = (y - cy) / ry;
          const nz = (z - cz) / radius;
          if (nx * nx + ny * ny + nz * nz <= 1.05) {
            put(x, y, z, block);
          }
        }
      }
    }
  }

  function drawTentacle(points, startRadius, endRadius, block, accents) {
    const lengths = [];
    let totalLength = 0;

    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i];
      const b = points[i + 1];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const dz = b[2] - a[2];
      const length = Math.sqrt(dx * dx + dy * dy + dz * dz);
      lengths.push(length);
      totalLength += length;
    }

    let travelled = 0;
    let serial = 0;

    for (let i = 0; i < points.length - 1; i++) {
      const a = points[i];
      const b = points[i + 1];
      const dx = b[0] - a[0];
      const dy = b[1] - a[1];
      const dz = b[2] - a[2];
      const steps = Math.max(
        1,
        Math.ceil(Math.max(Math.abs(dx), Math.abs(dy), Math.abs(dz)))
      );

      for (let s = 0; s <= steps; s++) {
        if (i > 0 && s === 0) {
          continue;
        }

        const localT = s / steps;
        const distance = travelled + lengths[i] * localT;
        const t = totalLength === 0 ? 0 : distance / totalLength;

        const cx = Math.round(a[0] + dx * localT);
        const cy = Math.round(a[1] + dy * localT);
        const cz = Math.round(a[2] + dz * localT);
        const radius =
          startRadius + (endRadius - startRadius) * t;

        if (cy <= 2) {
          footing(cx, cz);
        }

        fillTube(cx, cy, cz, radius, block);

        if (accents && serial % 4 === 2 && radius > 1.7) {
          const ry = Math.max(1.55, radius * 0.78);
          const accentY = cy + Math.max(1, Math.floor(ry * 0.8));
          put(cx, accentY, cz, "minecraft:sea_lantern");
        }

        serial++;
      }

      travelled += lengths[i];
    }
  }

  drawTentacle(
    [
      [18, 8, 25],
      [15, 7, 22],
      [13, 6, 18],
      [10, 5, 14],
      [7, 4, 10],
      [5, 3, 7],
      [7, 2, 5]
    ],
    3.4,
    1.55,
    "minecraft:dark_prismarine",
    true
  );

  drawTentacle(
    [
      [30, 8, 25],
      [33, 7, 22],
      [35, 6, 18],
      [38, 5, 14],
      [41, 4, 10],
      [44, 3, 7],
      [42, 2, 5]
    ],
    3.2,
    1.55,
    "minecraft:prismarine",
    true
  );

  drawTentacle(
    [
      [23, 7, 23],
      [22, 6, 20],
      [22, 5, 16],
      [23, 4, 12],
      [25, 3, 8],
      [24, 2, 4],
      [21, 2, 3]
    ],
    3.0,
    1.55,
    "minecraft:dark_prismarine",
    true
  );

  drawTentacle(
    [
      [27, 7, 23],
      [28, 6, 20],
      [29, 5, 16],
      [31, 4, 12],
      [33, 3, 8],
      [32, 2, 4],
      [35, 2, 3]
    ],
    2.9,
    1.55,
    "minecraft:prismarine",
    true
  );

  drawTentacle(
    [
      [17, 9, 28],
      [13, 8, 27],
      [9, 7, 24],
      [6, 6, 22],
      [4, 5, 19],
      [4, 4, 16],
      [6, 2, 14]
    ],
    3.0,
    1.55,
    "minecraft:dark_prismarine",
    true
  );

  drawTentacle(
    [
      [31, 9, 28],
      [35, 8, 29],
      [39, 7, 27],
      [42, 6, 24],
      [45, 5, 21],
      [43, 4, 18],
      [45, 2, 16]
    ],
    3.2,
    1.55,
    "minecraft:prismarine",
    true
  );

  drawTentacle(
    [
      [19, 8, 32],
      [15, 7, 35],
      [11, 6, 38],
      [8, 5, 41],
      [11, 4, 44],
      [15, 2, 42]
    ],
    2.8,
    1.55,
    "minecraft:dark_prismarine",
    true
  );

  drawTentacle(
    [
      [29, 8, 32],
      [34, 7, 35],
      [38, 6, 38],
      [41, 5, 42],
      [38, 4, 45],
      [34, 2, 43]
    ],
    3.0,
    1.55,
    "minecraft:prismarine",
    true
  );

  for (let x = 17; x <= 31; x++) {
    for (let y = 12; y <= 26; y++) {
      const ox = (x - 24) / 7;
      const oy = (y - 19) / 7;
      const outer = ox * ox + oy * oy;

      if (outer <= 1) {
        put(x, y, 24, "minecraft:dark_prismarine");

        const ix = (x - 24) / 5.5;
        const iy = (y - 19) / 5;
        const inner = ix * ix + iy * iy;

        if (inner <= 0.52) {
          for (let z = 18; z <= 21; z++) {
            put(x, y, z, "minecraft:black_concrete");
          }
        } else {
          for (let z = 18; z <= 23; z++) {
            put(x, y, z, "minecraft:red_concrete");
          }
        }
      }
    }
  }

  const teeth = [
    [20, 16],
    [24, 15],
    [28, 16],
    [20, 22],
    [24, 23],
    [28, 22]
  ];

  for (let i = 0; i < teeth.length; i++) {
    const tooth = teeth[i];
    put(tooth[0], tooth[1], 17, "minecraft:calcite");

    if (i < 3) {
      put(tooth[0], tooth[1] - 1, 17, "minecraft:calcite");
    } else {
      put(tooth[0], tooth[1] + 1, 17, "minecraft:calcite");
    }
  }

  drawTentacle(
    [
      [18, 24, 23],
      [15, 25, 21]
    ],
    1.9,
    1.6,
    "minecraft:prismarine",
    false
  );

  drawTentacle(
    [
      [30, 24, 23],
      [33, 25, 21]
    ],
    1.9,
    1.6,
    "minecraft:prismarine",
    false
  );

  put(15, 25, 21, "minecraft:black_concrete");
  put(14, 25, 21, "minecraft:sea_lantern");
  put(14, 25, 20, "minecraft:black_concrete");

  put(33, 25, 21, "minecraft:black_concrete");
  put(34, 25, 21, "minecraft:sea_lantern");
  put(34, 25, 20, "minecraft:black_concrete");

  return {
    name: "Leviathan Breach",
    seatY: 0,
    anchors: {
      door: [24, 1, 6],
      breach: [24, 19, 18],
      quay: [8, 2, 8],
      crown: [24, 35, 33]
    }
  };
}

