export const envelope = [15, 18, 15];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const index = api.instance.index;
  const count = api.instance.count;

  const randoms = new Array(24);
  for (let i = 0; i < randoms.length; i += 1) {
    randoms[i] = api.random();
  }

  const clamp = function (value, low, high) {
    return Math.max(low, Math.min(high, value));
  };

  const put = function (x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  };

  const centerX = 6 + ((index + Math.floor(randoms[0] * 7)) % 4);
  const lateralLean = ((index + count + Math.floor(randoms[1] * 3)) % 3) - 1;
  const headX = clamp(centerX + lateralLean, 2, W - 3);

  const torsoZ = 4 + ((index + count + Math.floor(randoms[2] * 3)) % 3);
  const headZ = torsoZ + 2;
  const torsoRadius = 3 + ((index + Math.floor(randoms[3] * 2)) % 2);
  const damage = (index + count + Math.floor(randoms[4] * 4)) % 4;

  const palettes = [
    [
      "minecraft:dark_prismarine",
      "minecraft:deepslate_bricks",
      "minecraft:prismarine"
    ],
    [
      "minecraft:prismarine",
      "minecraft:dark_prismarine",
      "minecraft:prismarine_bricks"
    ],
    [
      "minecraft:deepslate",
      "minecraft:polished_blackstone",
      "minecraft:dark_prismarine"
    ],
    [
      "minecraft:cyan_concrete",
      "minecraft:blue_concrete",
      "minecraft:prismarine"
    ]
  ];

  const palette = palettes[
    (index + count + Math.floor(randoms[6] * palettes.length)) % palettes.length
  ];

  const core = palette[0];
  const shadow = palette[1];
  const highlight = palette[2];

  const foundation =
    (index + count) % 2 === 0
      ? "minecraft:stone_bricks"
      : "minecraft:deepslate_bricks";

  const lower =
    (index + Math.floor(randoms[7] * 2)) % 2 === 0
      ? "minecraft:cobblestone"
      : "minecraft:mossy_cobblestone";

  const rubbleTop = "minecraft:mossy_cobblestone";
  const wet = "minecraft:dark_prismarine";
  const wetLight = "minecraft:prismarine";

  const foamA = "minecraft:calcite";
  const foamB = "minecraft:light_blue_concrete";

  const terrainHeight = new Array(D);
  const terrainTop = new Array(D);

  for (let z = 0; z < D; z += 1) {
    terrainHeight[z] = new Array(W);
    terrainTop[z] = new Array(W);

    for (let x = 0; x < W; x += 1) {
      let h = api.heightAt(x, z);
      if (!Number.isFinite(h)) {
        h = 0;
      }

      h = Math.floor(h);
      terrainHeight[z][x] = h;

      let top = h + 1;
      if (top < 1) {
        top = 1;
      }
      if (top >= H) {
        top = H - 1;
      }

      terrainTop[z][x] = top;
    }
  }

  let rise = terrainHeight[torsoZ][centerX];
  if (rise < 0) {
    rise = 0;
  }
  const lift = clamp(Math.floor(rise), 0, 2);

  const bend =
    ((index + count + Math.floor(randoms[5] * 7)) % 5) - 2;
  const widthJitter = Math.floor(randoms[8] * 3);

  const trailCenter = function (z) {
    const offset = Math.round(((z - 7) * bend) / 9);
    return clamp(centerX + offset, 2, W - 3);
  };

  const trailWidth = function (z) {
    let width = z < 3 ? 6 : (z > 10 ? 6 : 5);
    if ((z + index + widthJitter) % 4 === 0) {
      width += 1;
    }
    return width;
  };

  const trailBounds = function (z) {
    const center = trailCenter(z);
    const width = trailWidth(z);
    return [
      Math.max(0, center - width),
      Math.min(W - 1, center + width)
    ];
  };

  for (let z = 0; z < D; z += 1) {
    const center = trailCenter(z);
    const bounds = trailBounds(z);

    for (let x = bounds[0]; x <= bounds[1]; x += 1) {
      const top = terrainTop[z][x];

      for (let y = 0; y <= top; y += 1) {
        let block = foundation;

        if (y === 0) {
          block = lower;
        }

        if (y === top) {
          if (
            Math.abs(x - center) <= 2 &&
            (x + z + index) % 4 !== 0
          ) {
            block = wet;
          } else if ((x + z * 2 + count) % 5 === 0) {
            block = rubbleTop;
          }
        }

        put(x, y, z, block);
      }
    }
  }

  const laneOffsets = [-2, 0, 2];

  for (let z = 1; z < D; z += 1) {
    const center = trailCenter(z);

    for (let lane = 0; lane < laneOffsets.length; lane += 1) {
      let wobble = 0;

      if (lane === 0 && (z + index) % 3 === 0) {
        wobble = -1;
      } else if (lane === 2 && (z + index + 1) % 3 === 0) {
        wobble = 1;
      }

      const x = clamp(
        center + laneOffsets[lane] + wobble,
        0,
        W - 1
      );

      let y = terrainTop[z][x];
      if (
        lane === 1 &&
        (z + index + widthJitter) % 3 === 0
      ) {
        y += 1;
      }

      if (y >= H) {
        y = H - 1;
      }

      put(
        x,
        y,
        z,
        lane === 1 || (z + lane + index) % 3 === 0
          ? wetLight
          : wet
      );
    }
  }

  const debrisSalt = Math.floor(randoms[9] * 7);

  for (let sideIndex = 0; sideIndex < 2; sideIndex += 1) {
    const side = sideIndex === 0 ? -1 : 1;

    for (let k = 0; k < 6; k += 1) {
      const z = (k * 2 + sideIndex + index + debrisSalt) % 5;
      const bounds = trailBounds(z);
      const edge = side < 0 ? bounds[0] : bounds[1];

      const outward =
        (k + sideIndex + index + damage) % 3 === 0 ? 1 : 0;

      let x = edge + side * outward;
      if (x < 0 || x >= W) {
        x = edge;
      }

      const height =
        1 + ((k + sideIndex + index + debrisSalt) % 3);

      const brokenChunk =
        (k + sideIndex + index + damage + debrisSalt) % 5 === 0;

      if (!brokenChunk || outward === 0) {
        for (let y = 0; y <= height; y += 1) {
          put(
            x,
            y,
            z,
            y === height &&
            (k + sideIndex + index) % 2 === 0
              ? rubbleTop
              : lower
          );
        }
      }

      if ((k + sideIndex + index) % 2 === 0) {
        const inwardX = clamp(edge - side, 0, W - 1);
        const inwardHeight =
          1 + ((k + sideIndex + count) % 2);

        for (let y = 1; y <= inwardHeight; y += 1) {
          put(
            inwardX,
            y,
            z,
            (y + k + sideIndex + index) % 2 === 0
              ? rubbleTop
              : foundation
          );
        }
      }
    }
  }

  const waveSide =
    (index + count + Math.floor(randoms[10] * 2)) % 2 === 0
      ? -1
      : 1;

  const waveStartZ =
    1 + ((index + Math.floor(randoms[11] * 2)) % 2);

  const waveLength =
    4 + ((index + count + Math.floor(randoms[12] * 3)) % 3);

  for (let t = 0; t <= waveLength; t += 1) {
    const z = waveStartZ + t;
    const x = clamp(
      trailCenter(z) +
        waveSide * (4 - Math.floor(t / 2)),
      1,
      W - 2
    );

    const waveY = 1 + Math.floor((3 * t) / 4);

    for (let dx = -1; dx <= 1; dx += 1) {
      for (let y = waveY; y <= waveY + 1; y += 1) {
        put(
          x + dx,
          y,
          z,
          (t + dx + index + count) % 5 === 0
            ? wetLight
            : wet
        );
      }
    }

    if (t === waveLength || (t + index) % 3 === 0) {
      put(x, waveY + 2, z, foamA);

      if (t === waveLength) {
        put(
          clamp(x + waveSide, 0, W - 1),
          waveY + 2,
          z,
          foamB
        );
      }
    }
  }

  const shellFor = function (x, y, z) {
    const pattern =
      (x * 7 + y * 11 + z * 13 + index * 17 + count * 3) % 31;

    if (pattern === 0 || pattern === 1) {
      return shadow;
    }

    if (pattern === 2 || pattern === 3 || pattern === 4) {
      return highlight;
    }

    return core;
  };

  const fillEllipsoid = function (
    cx,
    cy,
    cz,
    rx,
    ry,
    rz,
    selector,
    allowScar
  ) {
    const minX = Math.max(0, cx - rx);
    const maxX = Math.min(W - 1, cx + rx);
    const minY = Math.max(0, cy - ry);
    const maxY = Math.min(H - 1, cy + ry);
    const minZ = Math.max(0, cz - rz);
    const maxZ = Math.min(D - 1, cz + rz);
    const scarMod = 9 + damage;

    for (let y = minY; y <= maxY; y += 1) {
      const dy = y - cy;

      for (let z = minZ; z <= maxZ; z += 1) {
        const dz = z - cz;

        for (let x = minX; x <= maxX; x += 1) {
          const dx = x - cx;
          const norm =
            (dx * dx) / (rx * rx) +
            (dy * dy) / (ry * ry) +
            (dz * dz) / (rz * rz);

          if (norm <= 1) {
            const scar =
              allowScar &&
              damage > 0 &&
              y > cy - ry + 1 &&
              norm > 0.84 &&
              (x * 5 + y * 7 + z * 11 + index + damage) %
                scarMod ===
                0;

            if (!scar) {
              put(x, y, z, selector(x, y, z));
            }
          }
        }
      }
    }
  };

  fillEllipsoid(
    centerX,
    5 + lift,
    torsoZ,
    torsoRadius,
    3,
    3,
    shellFor,
    true
  );

  fillEllipsoid(
    headX,
    7 + lift,
    headZ,
    3,
    3,
    3,
    shellFor,
    true
  );

  fillEllipsoid(
    centerX,
    4 + lift,
    torsoZ + 1,
    3,
    2,
    2,
    function () {
      return shadow;
    },
    false
  );

  const finHeight =
    4 + ((index + count + Math.floor(randoms[13] * 3)) % 3);

  const finLean =
    ((index + Math.floor(randoms[14] * 3) + count) % 3) - 1;

  const finBaseY = 8 + lift;

  for (let t = 0; t <= finHeight; t += 1) {
    const y = finBaseY + t;
    const finX = clamp(
      headX + finLean * Math.floor(t / 3),
      1,
      W - 2
    );
    const finZ = headZ - 1 - Math.floor(t / 2);

    for (let dx = -1; dx <= 1; dx += 1) {
      for (let z = finZ; z <= finZ + 1; z += 1) {
        const chipped =
          damage >= 2 &&
          t === finHeight &&
          (dx + z + index + count) % 5 === 0;

        if (!chipped) {
          put(
            finX + dx,
            y,
            z,
            (t + z + index) % 4 === 0
              ? highlight
              : core
          );
        }
      }
    }
  }

  const sideFinBase =
    2 + ((index + count + Math.floor(randoms[15] * 3)) % 2);

  for (let sideIndex = 0; sideIndex < 2; sideIndex += 1) {
    const side = sideIndex === 0 ? -1 : 1;
    const maxExtra =
      side < 0
        ? headX - 2
        : W - 1 - headX - 2;

    let length = Math.min(
      sideFinBase +
        ((sideIndex + index + count) % 2),
      maxExtra
    );

    if (length < 1) {
      length = 1;
    }

    for (let d = 0; d <= length; d += 1) {
      const x = headX + side * (2 + d);
      const y0 =
        6 + lift - Math.floor(d / 2);
      const z0 =
        headZ - 1 + ((d + sideIndex + index) % 2);

      for (let y = y0; y <= y0 + 1; y += 1) {
        for (let z = z0; z <= z0 + 1; z += 1) {
          const chipped =
            damage === 3 &&
            d === length &&
            (y + z + sideIndex + index) % 4 === 0;

          if (!chipped) {
            put(
              x,
              y,
              z,
              (d + sideIndex + index) % 3 === 0
                ? highlight
                : core
            );
          }
        }
      }
    }
  }

  const eyeY = 8 + lift;
  const eyeZ = headZ + 2;

  for (let side = -1; side <= 1; side += 2) {
    const eyeBlock = "minecraft:yellow_concrete";

    put(headX + side, eyeY, eyeZ, eyeBlock);
    put(headX + side, eyeY, eyeZ + 1, eyeBlock);
  }

  const mouthY = 6 + lift;

  for (let dx = -2; dx <= 2; dx += 1) {
    put(
      headX + dx,
      mouthY,
      headZ + 2,
      "minecraft:black_concrete"
    );

    if ((dx + index + count) % 2 === 0) {
      put(
        headX + dx,
        mouthY,
        headZ + 3,
        "minecraft:black_concrete"
      );
    }
  }

  for (let dx = -1; dx <= 1; dx += 1) {
    if ((dx + index) % 3 !== 0) {
      put(
        headX + dx,
        mouthY - 1,
        headZ + 3,
        "minecraft:white_concrete"
      );
    }
  }

  const gillBlock =
    (index + count) % 2 === 0
      ? "minecraft:cyan_concrete"
      : highlight;

  for (let sideIndex = 0; sideIndex < 2; sideIndex += 1) {
    const side = sideIndex === 0 ? -1 : 1;

    for (let g = 0; g < 3; g += 1) {
      put(
        headX + side * 3,
        6 + lift + (g % 2),
        headZ - 1 + g,
        gillBlock
      );
    }
  }

  const drawTentacle = function (
    startX,
    startY,
    startZ,
    endZ,
    drift,
    drop,
    material,
    phase
  ) {
    const points = [];
    const length = Math.max(1, endZ - startZ);

    for (let z = startZ; z <= endZ; z += 1) {
      const progress = (z - startZ) / length;
      const x = clamp(
        Math.round(startX + drift * progress),
        1,
        W - 2
      );
      const y = clamp(
        Math.round(startY - drop * progress),
        1,
        H - 2
      );

      const radius = progress < 0.72 ? 1 : 0;

      for (let dx = -radius; dx <= radius; dx += 1) {
        for (let dy = -radius; dy <= radius; dy += 1) {
          const roll =
            (x * 3 + y * 5 + z * 7 + phase + index) % 11;

          let block = material;
          if (roll === 0) {
            block = highlight;
          } else if (roll === 1) {
            block = shadow;
          }

          put(x + dx, y + dy, z, block);
        }
      }

      points.push([x, y, z]);
    }

    return points;
  };

  const paths = [];

  const centralDrift =
    ((index + count + Math.floor(randoms[16] * 5)) % 3) - 1;

  const leftDrift =
    -1 -
    ((index + count + Math.floor(randoms[17] * 2)) % 2);

  const rightDrift =
    1 +
    ((index + Math.floor(randoms[18] * 2) + count) % 2);

  const sideSign =
    (index + count + Math.floor(randoms[19] * 2)) % 2 === 0
      ? -1
      : 1;

  paths.push(
    drawTentacle(
      centerX,
      3 + lift,
      torsoZ + 1,
      D - 1,
      centralDrift,
      2 + lift,
      core,
      0
    )
  );

  paths.push(
    drawTentacle(
      centerX - 2,
      3 + lift,
      torsoZ + 1,
      D - 1,
      leftDrift,
      2 + lift,
      shadow,
      1
    )
  );

  paths.push(
    drawTentacle(
      centerX + 2,
      3 + lift,
      torsoZ + 1,
      D - 1,
      rightDrift,
      2 + lift,
      core,
      2
    )
  );

  const sideEnd =
    11 +
    ((index + count + Math.floor(randoms[20] * 2)) % 2);

  paths.push(
    drawTentacle(
      centerX + sideSign * 2,
      3 + lift,
      torsoZ - 1,
      sideEnd,
      sideSign *
        (1 + ((index + Math.floor(randoms[21] * 2)) % 2)),
      2 + lift,
      highlight,
      3
    )
  );

  for (let p = 0; p < paths.length; p += 1) {
    const path = paths[p];

    for (let q = 1; q < path.length - 1; q += 2) {
      if ((q + p + index + damage) % 3 !== 0) {
        const point = path[q];
        let cupY = point[1] + 1;

        if (cupY >= H) {
          cupY = H - 1;
        }

        put(
          point[0],
          cupY,
          point[2],
          highlight
        );
      }
    }
  }

  const drawPlume = function (
    startX,
    startY,
    startZ,
    length,
    driftX,
    driftZ,
    phase
  ) {
    const points = [];
    const denominator = length > 0 ? length : 1;
    let previousX = 0;
    let previousZ = 0;

    for (let t = 0; t <= length; t += 1) {
      const y = startY + t;
      if (y < 0 || y >= H) {
        break;
      }

      const x = clamp(
        Math.round(startX + (driftX * t) / denominator),
        0,
        W - 1
      );

      const z = clamp(
        Math.round(startZ + (driftZ * t) / denominator),
        0,
        D - 1
      );

      const block =
        (t + phase + index) % 3 === 0
          ? foamB
          : foamA;

      if (t === 0) {
        put(x, y, z, block);
      } else {
        if (x !== previousX || z !== previousZ) {
          put(previousX, y, previousZ, foamB);

          if (x !== previousX && z !== previousZ) {
            put(previousX, y, z, foamB);
          }
        }

        put(x, y, z, block);
      }

      points.push([x, y, z]);
      previousX = x;
      previousZ = z;
    }

    if (points.length > 0) {
      const last = points[points.length - 1];
      const branchDirection = phase % 2 === 0 ? 1 : -1;

      for (let k = 1; k <= 2; k += 1) {
        const branchX = clamp(
          last[0] + branchDirection * k,
          0,
          W - 1
        );

        put(
          branchX,
          last[1],
          last[2],
          k === 1 ? foamB : foamA
        );

        if (k === 1 && last[1] > 0) {
          put(
            branchX,
            last[1] - 1,
            last[2],
            foamA
          );
        }
      }

      const branchZ = clamp(
        last[2] + (phase % 2 === 0 ? 1 : -1),
        0,
        D - 1
      );

      if (branchZ !== last[2]) {
        put(last[0], last[1], branchZ, foamB);
      }
    }
  };

  const mainLength =
    4 + ((index + count + Math.floor(randoms[22] * 4)) % 3);

  const mainLean =
    ((index + count + Math.floor(randoms[23] * 5)) % 3) - 1;

  drawPlume(
    headX - 2,
    9 + lift,
    headZ - 1,
    mainLength,
    mainLean,
    0,
    1
  );

  const sidePlumeLength =
    3 + ((index + count + Math.floor(randoms[12] * 4)) % 3);

  const sidePlumeLean =
    ((index + Math.floor(randoms[14] * 5) + count) % 3) - 1;

  drawPlume(
    headX + 2,
    8 + lift,
    headZ,
    sidePlumeLength,
    0,
    sidePlumeLean,
    2
  );

  if (
    (index + count + Math.floor(randoms[15] * 4)) % 3 !==
    1
  ) {
    const thirdLength =
      2 + ((index + count + Math.floor(randoms[16] * 3)) % 2);

    drawPlume(
      centerX,
      10 + lift,
      headZ,
      thirdLength,
      sideSign,
      0,
      3
    );
  }

  for (let bit = 0; bit < 5; bit += 1) {
    const markerZ = 8 + bit;
    const markerX = clamp(
      trailCenter(markerZ) + (bit % 2 === 0 ? -2 : 2),
      0,
      W - 1
    );

    let markerY = terrainTop[markerZ][markerX] + 1;
    if (markerY >= H) {
      markerY = H - 1;
    }

    const marked =
      ((index >> bit) & 1) === 1;

    put(
      markerX,
      markerY,
      markerZ,
      marked
        ? "minecraft:light_blue_concrete"
        : "minecraft:blue_concrete"
    );

    if (marked && markerY + 1 < H) {
      put(
        markerX,
        markerY + 1,
        markerZ,
        foamB
      );
    }
  }

  const titles = [
    "Aegean Maw",
    "Quaybreaker",
    "Blackfin Surge",
    "Many-Armed Breaker",
    "Brine Stalker",
    "Foam-Crowned Horror",
    "Tide Wretch",
    "Suction-Cup Terror"
  ];

  const titleIndex =
    (index + count + Math.floor(randoms[5] * titles.length)) %
    titles.length;

  const seaX = trailCenter(0);
  const cityX = trailCenter(D - 1);

  return {
    name: titles[titleIndex] + " " + (index + 1),
    seatY: 0,
    anchors: {
      sea: [seaX, terrainTop[0][seaX], 0],
      cityward: [
        cityX,
        terrainTop[D - 1][cityX],
        D - 1
      ],
      monster: [headX, 7 + lift, headZ + 3]
    }
  };
}
